    struct compat_video_spu_palette __user *native_palette;
    int ret;

    native_palette = kmalloc(sizeof(struct compat_video_spu_palette), GFP_KERNEL);
    if (!native_palette)
        return -ENOMEM;

    if (copy_from_user(native_palette, up, sizeof(struct compat_video_spu_palette))) {
