int set_subtitle_palette(unsigned int fd, unsigned int cmd, struct compat_video_spu_palette __user *up) {
    int i;
    int ret;
    struct video_spu_palette __user *p;
    struct compat_video_spu_palette kspu;

    if (copy_from_user(&kspu, up, sizeof(kspu)))
        return -EFAULT;

    p = compat_alloc_user_space(sizeof(struct video_spu_palette));
    if (!p)
        return -EFAULT;

    for (i = 0; i < 16; i++) {
        p->palette[i] = kspu.palette[i];
    }

    p->length = kspu.length;

    ret = ioctl(fd, cmd, p);
    if (ret < 0)
        return ret;

    return 0;
}

int set_subtitle_palette(unsigned int fd, unsigned int cmd, struct compat_video_spu_palette __user *up) {
