#include <linux/compat.h>
#include <linux/uaccess.h>
#include <linux/ioctl.h>

int set_subtitle_palette(unsigned int fd, unsigned int cmd, struct compat_video_spu_palette __user *up) {
    int ret;
    struct compat_video_spu_palette native_palette;
    unsigned int len;

    if (copy_from_user(&native_palette, up, sizeof(native_palette)))
        return -EFAULT;

    len = native_palette.length;

    if (len > sizeof(native_palette.pal)) {
        return -EINVAL;
    }

    ret = 0;
    if (ioctl(fd, cmd, &native_palette) < 0)
        ret = -errno;

    return ret;
}
